def isPalindrome(num):
    original = str(num)
    reversed_str = original[::-1]
    return original == reversed_str

n = int(input('Enter a number: '))
if isPalindrome(n):
    print(n, 'is a palindrome')
else:
    print(n, 'is not a palindrome')

