def minMax(numbers):
    return min(numbers), max(numbers)

small, large = minMax([3, 7, 1, 9])
print(small, large)   # prints: 1 9

Listing multiple comma-separated values after 'return' makes Python pack them into a tuple, which the caller unpacks into separate variables.

def checkDivisibleBy7(num):
    if num % 7 == 0:
        print(num, 'is divisible by 7')
    else:
        print(num, 'is not divisible by 7')

n = int(input('Enter a number: '))
checkDivisibleBy7(n)

def checkDeterminant(a, b, c):
    determinant = b**2 - 4*a*c
    if determinant > 0:
        print('Determinant', determinant, '- two real distinct roots')
    elif determinant == 0:
        print('Determinant', determinant, '- two equal real roots')
    else:
        print('Determinant', determinant, '- no real roots (complex roots)')

a, b, c = 1, -5, 6
checkDeterminant(a, b, c)

def toTitleCase(text):
    return text.title()

print(toTitleCase('computer science is fun'))   # prints: Computer Science Is Fun

(Note: Python's built-in str.title() already does exactly this; a from-scratch version would split the string on spaces, capitalise the first letter of each word, then join them back with spaces.)

def deleteChar(text, char):
    result = ''
    for ch in text:
        if ch != char:
            result += ch
    return result

print(deleteChar('banana', 'a'))   # prints: bnn

def replaceSpacesWithHyphen(sentence):
    return sentence.replace(' ', '-')

print(replaceSpacesWithHyphen('this is a test'))   # prints: this-is-a-test

def findLargest(numbers):
    return max(numbers)

print(findLargest([4, 19, 2, 77, 15]))   # prints: 77

